contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool _isOwner, address _target, uint _value) public payable {
        require(msg.sender != address(0));
        uint256 beforeBalance = address(c).balance;

        bool reverted;
        if (_isOwner) {
            c.sendMoney(_target, _value);
            reverted = false;
            require(address(c).balance <= beforeBalance);

            c.withdrawAll();
            reverted = false;
            require(address(c).balance == 0);
        } else {
            try c.sendMoney(_target, _value) {
                reverted = false;
            } catch {
                reverted = true;
            }

            if (!reverted) {
                require(address(c).balance <= beforeBalance);

                try c.withdrawAll() {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        }

        if (_isOwner) {
            assert(address(c).balance == 0);
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _value, address _target) public payable {
        require(address(c).balance == 0);
        require(address(this).balance >= _value + 1);
        require(_target != address(0));

        c.fallback();

        uint256 afterDeposit = address(c).balance;
        require(afterDeposit == _value);

        uint256 beforeBalance = address(c).balance;

        try c.sendMoney(_target, _value) {
            assert(address(c).balance == beforeBalance - _value);
        } catch {
            assert(address(c).balance == beforeBalance);
        }
    }

    receive() external payable {}
    fallback() external payable {}
}

