contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint value) public payable {
        require(address(this).balance >= value, "insufficient balance");

        // Set up: as owner, deliberately send some Ether into C so there is a balance to protect,
        // and bump depositsCount via the fallback.
        (bool sentToC) = address(c).call{value: value}("");
        require(sentToC, "send to C failed");

        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount();

        // Attempt to move Ether out of C via sendMoney. Because the test contract is the
        // deployer, it is the owner, so this must succeed and move exactly `value` out.
        bool reverted;
        try c.sendMoney(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterCount = c.depositsCount();

        // General rule: an owner-driven sendMoney must not revert and must move exactly `value`
        // of Ether out of C, with depositsCount unaffected by the transfer.
        assert(!reverted && afterBalance == beforeBalance - value && afterCount == beforeCount);
    }

    receive() external payable {}
}

