contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address target, uint amount) public payable {
        require(msg.sender != address(this));
        require(address(this).balance >= amount);
        require(target != address(0));

        uint beforeDeposits = c.depositsCount();
        uint beforeBal = address(c).balance;

        (bool okFallback, ) = address(c).call{value: amount}("");
        bool fbReverted = !okFallback;

        uint afterDeposits = c.depositsCount();
        uint afterBal = address(c).balance;

        if (address(this) == c.owner()) {
            assert(!fbReverted);
            assert(afterDeposits == beforeDeposits + 1);
            assert(afterBal == beforeBal + amount);
        } else {
            assert(fbReverted);
            assert(afterDeposits == beforeDeposits);
            assert(afterBal == beforeBal);
        }

        bool withdrawReverted;
        c.withdrawAll();
        withdrawReverted = false;
        if (address(this) != c.owner()) {
            assert(withdrawReverted);
        }
    }

    receive() external payable {}
}

