contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address attacker, uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "not enough balance for deposit");

        // State setup: send ETH into C through its payable fallback.
        uint cBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // Deposit ether into C; this changes state and must be a top-level call.
        (bool depositOk,) = address(c).call{value: depositAmount}("");

        // Read observable state after deposit.
        uint cAfterDeposit = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // A non-owner must not be able to withdraw or send money from C.
        bool nonOwnerWithdrawAllReverted;
        try c.withdrawAll() {
            nonOwnerWithdrawAllReverted = false;
        } catch {
            nonOwnerWithdrawAllReverted = true;
        }

        bool nonOwnerSendMoneyReverted;
        try c.sendMoney(attacker, withdrawAmount) {
            nonOwnerSendMoneyReverted = false;
        } catch {
            nonOwnerSendMoneyReverted = true;
        }

        uint cAfterNonOwnerAttempts = address(c).balance;

        assert(
            depositOk &&
            cAfterDeposit == cBefore + depositAmount &&
            depositsAfter == depositsBefore + 1 &&
            nonOwnerWithdrawAllReverted &&
            nonOwnerSendMoneyReverted &&
            cAfterNonOwnerAttempts == cAfterDeposit
        );
    }
}

