        // depositsCount must not change because no fallback is triggered on the contract itself.
        require(afterSendBalance == beforeSendBalance - sendAmount);
        require(afterSendCount == beforeSendCount);

        // Now the contract has enough Ether for a withdrawal of at most its remaining balance.
        require(withdrawAmount <= afterSendBalance);

        c.withdraw(withdrawAmount);

        uint finalBalance = address(c).balance;

        assert(finalBalance == afterSendBalance - withdrawAmount);
    }

    receive() external payable {}
}

